std::vector<Node> result;
if (start_idx < 0 || end_idx < 0 || start_idx >= graph.SNodes().size() || end_idx >= graph.SNodes().size()) {
    return result;
}

// Initialize start and end nodes
auto& start_node = graph.SNodes()[start_idx];
auto& end_node = graph.SNodes()[end_idx];

// Reset all nodes for new search
for (auto& node : graph.SNodes()) {
    node.g_value = std::numeric_limits<float>::max();
    node.h_value = std::numeric_limits<float>::max();
    node.visited = false;
    node.parent = nullptr;
}

// Initialize start node
graph.SNodes()[start_idx].g_value = 0.0f;
graph.SNodes()[start_idx].h_value = graph.SNodes()[start_idx].distance(end_node);

// Open list as vector of pointers to nodes
std::vector<RouteModel::Node*> open_list;
open_list.push_back(&graph.SNodes()[start_idx]);

while (!open_list.empty()) {
    // Find node with minimum f_value (g + h)
    int best_index = 0;
    float best_f_value = open_list[0]->g_value + open_list[0]->h_value;

    for (int i = 1; i < open_list.size(); ++i) {
        float f_value = open_list[i]->g_value + open_list[i]->h_value;
        if (f_value < best_f_value) {
            best_f_value = f_value;
            best_index = i;
        }
    }

    // Get current node
    RouteModel::Node* current_node = open_list[best_index];
    open_list.erase(open_list.begin() + best_index);

    // If we reached the end node, construct path
    if (current_node == &end_node) {
        return construct_final_path(current_node);
    }

    // Mark as visited
    current_node->visited = true;

    // Add neighbors
    current_node->find_neighbors();

    for (auto* neighbor : current_node->neighbors) {
        if (neighbor->visited) {
            continue;
        }

        float tentative_g_value = current_node->g_value + current_node->distance(*neighbor);

        if (tentative_g_value < neighbor->g_value) {
            neighbor->parent = current_node;
            neighbor->g_value = tentative_g_value;
            neighbor->h_value = neighbor->distance(end_node);

            // If not in open list, add it
            bool in_open_list = false;
            for (auto* node : open_list) {
                if (node == neighbor) {
                    in_open_list = true;
                    break;
                }
            }

            if (!in_open_list) {
                open_list.push_back(neighbor);
            }
        }
    }
}

// No path found
return result;

